import { createContext } from "react";
import type {
  LogErrorFn,
  OnboardingTooltipConfig,
  ShowToastFn,
  UpdateToastFn,
  DismissToastFn,
  IsToastVisibleFn,
  TrackFn,
} from "../types";
import {
  defaultShowToast,
  defaultUpdateToast,
  defaultDismissToast,
  defaultIsToastVisible,
} from "../Toaster";

export interface InspectorContextValue {
  logError: LogErrorFn;
  track: TrackFn;
  showToast: ShowToastFn;
  updateToast: UpdateToastFn;
  dismissToast: DismissToastFn;
  isToastVisible: IsToastVisibleFn;
  onboardingTooltips: OnboardingTooltipConfig[];
  socketReconnectAttempts?: number;
}

export const InspectorContext = createContext<InspectorContextValue>({
  logError: console.error,
  track: () => undefined,
  showToast: defaultShowToast,
  updateToast: defaultUpdateToast,
  dismissToast: defaultDismissToast,
  isToastVisible: defaultIsToastVisible,
  onboardingTooltips: [],
});
